{
  "technical_and_design_decisions": [
    "For Java chaincode transactional context (U1), implement a per-transaction TransactionContext instance injected as the first parameter to chaincode methods to ensure thread safety by avoiding shared state across concurrent transactions, prioritizing safety over minor performance overhead from instance creation.",
    "For protos package cleanup (U2/U3), move only non-generated utility code and extensions to the new protoutils package, leaving generated proto code in the original protos package, and maintain backward-compatible re-export aliases in the old protos/utils package for one major release to avoid breaking existing consumers.",
    "For Kafka health check backport (U4), limit changes to only the backported health check functionality, with no modifications to existing 1.4 LTS Kafka integration logic, to minimize regression risk.",
    "For read-only chaincode invoke (U5), implement a dedicated ReadOnlyInvoke invocation type rather than modifying existing access control checks for standard Invoke, to maintain backward compatibility for existing chaincode that uses standard Invoke for read-only operations.",
    "For service discovery external endpoint (U6), the new peer.discovery.externalEndpoint configuration option takes precedence over the existing PEER_GOSSIP_EXTERNALENDPOINT environment variable for service discovery advertisements, while retaining support for the existing env var for backward compatibility.",
    "For operations service version endpoint (U7), the /version endpoint is read-only and requires no authentication, as it only exposes non-sensitive version and build metadata.",
    "For Go sample refactoring (U8), preserve all original sample functionality, only refactoring code structure and style to be idiomatic Go, without adding new features or changing sample behavior."
  ],
  "assumptions": [
    "All code changes are made against the Hyperledger Fabric 1.4 LTS codebase, except for the Kafka health check backport which is pulled from the latest stable master branch commit.",
    "Existing unit and integration tests for all modified components are updated as part of development work, with no new test infrastructure required.",
    "The protos package cleanup (U2/U3) does not require modifications to existing proto file definitions, only reorganization of existing generated code and utility files.",
    "The read-only chaincode invoke (U5) does not require changes to the underlying ledger state validation logic, only access control checks and chaincode method validation.",
    "Development is performed by a single developer with existing familiarity with the Hyperledger Fabric codebase, with no additional onboarding time required.",
    "No new external dependencies are added for any of the implemented features."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Implement per-transaction TransactionContext for Java chaincode",
      "activity_description": "Design and implement a thread-safe TransactionContext class for Java chaincode that holds the stub and related APIs, modify the Java chaincode runtime to inject a new TransactionContext instance as the first parameter to all chaincode method invocations, update existing Java chaincode samples to use the new parameter, and add unit tests for the new functionality.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A2",
      "activity_name": "Reorganize protos utilities to protoutils package",
      "activity_description": "Move all non-generated utility code and extensions from the protos/utils package to a new protoutils package, update all internal import references across the codebase, add backward-compatible re-export aliases in the old protos/utils package for one major release, and update package documentation to reference the new location. This activity covers both U2 and U3 as they are identical requirements.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "Backport Kafka health checks to Fabric 1.4 LTS",
      "activity_description": "Pull the Kafka health check implementation from the master branch, modify it to be compatible with the 1.4 LTS API and dependency versions, add unit and integration tests for the backported health checks, and update 1.4 LTS documentation to include the new Kafka health check configuration options.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A4",
      "activity_name": "Implement read-only chaincode invoke for channel readers",
      "activity_description": "Add a new ReadOnlyInvoke chaincode invocation type that only permits Get operations, modify access control checks to allow channel Reader permissions to call ReadOnlyInvoke, add runtime validation to reject any state-modifying operations when using ReadOnlyInvoke, and add test cases for the new permission model.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A5",
      "activity_name": "Add configurable external endpoint for service discovery",
      "activity_description": "Add a new peer.discovery.externalEndpoint configuration option that overrides the PEER_GOSSIP_EXTERNALENDPOINT value for service discovery advertisements, modify the service discovery logic to use the new config option when present, add unit tests for the configuration precedence logic, and update peer configuration and service discovery documentation.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A6",
      "activity_name": "Implement version endpoint for operations services",
      "activity_description": "Add a new /version HTTP endpoint to both peer and orderer operations services that returns the Fabric version, build commit hash, and Go runtime version, ensure the endpoint is accessible without authentication, add unit tests for the endpoint, and update operations service API documentation.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7",
      "activity_name": "Refactor samples to idiomatic Go",
      "activity_description": "Refactor all existing Hyperledger Fabric Go samples to follow Go best practices including proper error handling, context usage, idiomatic naming, and Go module structure, preserve all original sample functionality, add inline comments explaining idiomatic choices, and update sample README files.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A8",
      "activity_name": "Final integration and regression testing",
      "activity_description": "Run full integration and regression test suites across all implemented features to ensure no unintended side effects or breakages from the changes, fix any issues identified during testing.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 31
  }
}

